UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">La regola funziona come linea guida generale, ma ha due problemi concreti. Il primo: in molte città italiane l''affitto o il mutuo da solo può superare il 40-50% del reddito netto, rendendo il vincolo del 50% per tutte le necessità semplicemente irrealistico senza colpa di chi lo applica. Il secondo: tratta tutte le «necessità» o tutti i «desideri» come un blocco unico, senza dirti dove va davvero il denaro — se il problema è la spesa alimentare o i ristoranti, la regola non lo rivela.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">La regola funziona come linea guida generale, ma ha due problemi concreti. Il primo: in molte città italiane l''affitto o il mutuo da solo può superare il 40-50% del reddito netto, rendendo il vincolo del 50% per tutte le necessità semplicemente irrealistico senza colpa di chi lo applica. Il secondo: tratta tutte le «necessità» o tutti i «desideri» come un blocco unico, senza dirti dove va davvero il denaro — se il problema è la spesa alimentare o i ristoranti, la regola non lo rivela.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Reddito netto di 2.000 euro: la regola e un caso reale (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Regola 50/30/20</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Caso reale</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Necessità</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.000 (50%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.250 (62,5%)</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Desideri</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">600 (30%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">450 (22,5%)</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Risparmio</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">400 (20%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">300 (15%)</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Nel caso reale le necessità sono affitto 800 euro, spesa 300, bollette e trasporti 150: il solo affitto vale il 40% del reddito e il 50% non basta.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'regola-50-30-20-vs-budget-per-categoria' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">«Voglio 6.000€ per un viaggio tra 12 mesi» genera automaticamente un numero azionabile: 500€ al mese. «Vorrei fare un viaggio bello» non genera nulla di verificabile — a marzo non hai modo di sapere se sei in linea con l''obiettivo o già in ritardo.</p>',
