UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il risparmio va trattato come una voce di spesa, da mettere da parte a inizio mese e non con quello che avanza. Prima di tutto conviene costruire un <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a>.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il risparmio va trattato come una voce di spesa, da mettere da parte a inizio mese e non con quello che avanza. Prima di tutto conviene costruire un <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a>.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Esempio: famiglia con 3.000 euro netti al mese (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Categoria</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Budget</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Quota</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Casa (affitto o mutuo)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">900</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">30%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Spesa alimentare</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">600</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">20%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Trasporti</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">250</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">8,3%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Bollette</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">200</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">6,7%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Figli</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">250</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">8,3%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Salute</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">80</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2,7%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Tempo libero</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">220</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">7,3%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Spese annuali accantonate</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">100</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3,3%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Risparmio</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">400</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">13,3%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 font-semibold text-gray-900">Totale</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">3.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">100%</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Il risparmio è una voce come le altre, messa da parte a inizio mese. Le spese annuali (bollo, assicurazioni) sono divise per dodici.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'budget-familiare-mensile-come-farlo' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Bollo auto, assicurazione pagata in un''unica soluzione, revisione, TARI, manutenzione della caldaia: sono spese certe che arrivano una o due volte l''anno e mettono in crisi il bilancio del mese in cui cadono. Il metodo più semplice è sommarle, dividere per dodici e accantonare quella cifra ogni mese, come se fosse una spesa fissa.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Bollo auto, assicurazione pagata in un''unica soluzione, revisione, TARI, manutenzione della caldaia: sono spese certe che arrivano una o due volte l''anno e mettono in crisi il bilancio del mese in cui cadono. Il metodo più semplice è sommarle, dividere per dodici e accantonare quella cifra ogni mese, come se fosse una spesa fissa.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Le spese annuali trasformate in quota mensile (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Spesa</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">All''anno</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Al mese</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Bollo auto</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">250</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">20,83</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Assicurazione auto</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">600</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">50,00</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">TARI</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">280</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">23,33</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Manutenzione caldaia</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">100</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">8,33</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 font-semibold text-gray-900">Totale</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">1.230</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">102,50</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Importi di esempio. Accantonando poco più di 100 euro al mese, nessuna di queste spese mette in crisi il mese in cui arriva.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'spese-fisse-e-variabili-differenza' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dividi il prezzo per quanto guadagni all''ora: un acquisto da 120 euro può valere un''intera giornata di lavoro, e vista così la decisione cambia.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dividi il prezzo per quanto guadagni all''ora: un acquisto da 120 euro può valere un''intera giornata di lavoro, e vista così la decisione cambia.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Il prezzo in ore di lavoro, con 15 euro netti l''ora</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Acquisto</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Prezzo</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Ore di lavoro</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Maglietta</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">25 €</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1,7</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Cuffie</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">60 €</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Scarpe</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">120 €</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">8</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Smartwatch</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">300 €</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">20</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Smartphone</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">900 €</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">60</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">15 euro l''ora corrispondono a circa 2.400 euro netti al mese per 160 ore. Le scarpe da 120 euro valgono una giornata di lavoro.</p></figure>'),
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Registrare ogni spesa, anche piccola, rende visibile quanto pesano gli acquisti non pianificati. È uno dei motivi per cui <a href="/news/tracciare-spese-manualmente-vs-collegamento-bancario" class="text-accent hover:underline font-medium">tracciare le spese a mano</a> aumenta la consapevolezza.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Registrare ogni spesa, anche piccola, rende visibile quanto pesano gli acquisti non pianificati. È uno dei motivi per cui <a href="/news/tracciare-spese-manualmente-vs-collegamento-bancario" class="text-accent hover:underline font-medium">tracciare le spese a mano</a> aumenta la consapevolezza.</p><figure class="my-6 rounded-xl border border-border bg-white p-5"><figcaption class="mb-4 text-sm font-semibold text-gray-900">Piccole spese abituali: quanto costano in un anno</figcaption><div class="space-y-3"><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Un acquisto online da 25 euro a settimana</span><span class="whitespace-nowrap font-mono text-gray-900">1.300 €</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-expense" style="width:100.0%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Caffè e snack, 4 euro al giorno lavorativo</span><span class="whitespace-nowrap font-mono text-gray-900">880 €</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-loan" style="width:67.7%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Cibo a domicilio, 30 euro due volte al mese</span><span class="whitespace-nowrap font-mono text-gray-900">720 €</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-loan" style="width:55.4%"></div></div></div></div><p class="mt-4 text-xs text-muted">Esempi indicativi: 52 settimane, 220 giorni lavorativi, 24 consegne l''anno.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'acquisti-impulsivi-come-evitarli' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Si parte da 52 euro e si scende fino a 1. Il totale è lo stesso, ma lo sforzo maggiore cade a inizio anno, quando la motivazione è più alta, e a dicembre, il mese più costoso, si mettono da parte pochi euro.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Si parte da 52 euro e si scende fino a 1. Il totale è lo stesso, ma lo sforzo maggiore cade a inizio anno, quando la motivazione è più alta, e a dicembre, il mese più costoso, si mettono da parte pochi euro.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Quanto hai messo da parte a fine trimestre (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Trimestre</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Classica</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Al contrario</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">1° trimestre</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">91</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">598</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">2° trimestre</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">351</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.027</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">3° trimestre</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">780</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.287</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">4° trimestre</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.378</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.378</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Classica: da 1 a 52 euro. Al contrario: da 52 a 1. Totale uguale, ma al contrario a metà anno hai già messo da parte quasi i tre quarti della cifra.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'sfida-52-settimane-risparmio' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Parti da una percentuale realistica dello stipendio, anche il 5 o 10%, e aumentala gradualmente. Il <a href="/news/tasso-di-risparmio-cosa-e-come-calcolarlo" class="text-accent hover:underline font-medium">tasso di risparmio</a> è l''indicatore da tenere d''occhio nel tempo.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Parti da una percentuale realistica dello stipendio, anche il 5 o 10%, e aumentala gradualmente. Il <a href="/news/tasso-di-risparmio-cosa-e-come-calcolarlo" class="text-accent hover:underline font-medium">tasso di risparmio</a> è l''indicatore da tenere d''occhio nel tempo.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Stipendio netto di 1.800 euro (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Quota</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Al mese</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">In un anno</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">In 10 anni</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">5%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">90</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.080</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">13.252</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">10%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">180</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2.160</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">26.505</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">15%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">270</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3.240</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">39.757</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">20%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">360</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.320</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">53.010</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">In 10 anni: versamenti investiti con un rendimento ipotetico del 4% annuo, tasse escluse.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'paga-prima-te-stesso-risparmio-automatico' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se sfori una categoria, sposti soldi da un''altra: il totale resta sempre zero. Le scelte diventano esplicite invece che subite.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se sfori una categoria, sposti soldi da un''altra: il totale resta sempre zero. Le scelte diventano esplicite invece che subite.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Un mese a base zero (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Voce</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Importo</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Da assegnare</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Reddito netto del mese</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2.200</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2.200</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Spese fisse: affitto, bollette, assicurazioni, abbonamenti</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−1.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.200</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Risparmio e obiettivi</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−350</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">850</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Spesa e trasporti</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−530</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">320</td></tr><tr class="border-t border-border"><td class="px-3